const expected = (env.get('BACKEND_API_KEY') || env.get('SDI_EDC_BACKEND_KEY'));
const provided = msg.req.headers['x-api-key'];

if (!expected) {
    node.error('BACKEND_API_KEY is not set - refusing all requests');
    msg.statusCode = 500;
    msg.payload = { error: 'Backend not configured' };
    return [null, msg];
}

if (provided !== expected) {
    msg.statusCode = 401;
    msg.payload = { error: 'Unauthorized' };
    return [null, msg];
}

return [msg, null];

// shellId is expected to already be base64url-encoded by the caller,
// same convention used by the existing dsp-backend endpoints.
const shellId = msg.req.params.shellId;
const basyxBaseUrl = env.get('BASYX_BASE_URL') || env.get('SDI_AAS_URL') || 'http://127.0.0.1:8081';
msg.url = basyxBaseUrl + '/shells/' + shellId;
return msg;

const status = msg.statusCode;
const body = msg.payload;

if (status && (status < 200 || status >= 300)) {
    const detail = (body && body.messages) ? JSON.stringify(body.messages) : JSON.stringify(body);
    msg.statusCode = 404;
    msg.payload = { error: 'Shell nicht gefunden in Basyx (HTTP ' + status + '): ' + detail };
    return [null, msg];
}

if (!body || typeof body.id !== 'string' || !body.id) {
    msg.statusCode = 502;
    msg.payload = { error: 'Unerwartete Antwort von Basyx - keine gueltige Shell-id im Response enthalten.' };
    return [null, msg];
}

return [msg, null];

msg.shellData = msg.payload; // keep the full shell object for later
const submodels = msg.payload.submodels || [];

if (submodels.length === 0) {
    // Nothing to fan out to - skip split/join entirely so the flow
    // doesn't hang waiting for zero child messages.
    msg.payload = [];
    return [null, msg];
}

// Replace payload with just the refs array so the split node (on the plain
// "payload" property) hands each item straight to msg.payload downstream -
// splitting on a nested path like "payload.submodels" instead writes each
// item back into msg.payload.submodels, leaving msg.payload as the shell object.
msg.payload = submodels;
return [msg, null];

// The shape of a submodel reference can vary between Basyx setups - handle the
// common ones instead of assuming the AAS v3 {keys:[{value}]} form.
function extractSubmodelId(ref) {
    if (typeof ref === 'string') return ref;
    if (ref && Array.isArray(ref.keys) && ref.keys.length > 0 && ref.keys[0].value) return ref.keys[0].value;
    if (ref && typeof ref.value === 'string') return ref.value;
    if (ref && typeof ref.id === 'string') return ref.id;
    return null;
}

const smId = extractSubmodelId(msg.payload);
if (!smId) {
    node.error('Could not determine submodel id from reference: ' + JSON.stringify(msg.payload), msg);
    return null;
}

const basyxBaseUrl = env.get('BASYX_BASE_URL') || env.get('SDI_AAS_URL') || 'http://127.0.0.1:8081';
msg.url = basyxBaseUrl + '/submodels/' + Buffer.from(smId).toString('base64url');
return msg;

const shell = msg.shellData;
const submodels = msg.payload; // [] from the no-submodels path, or the joined array

msg.aasId = shell.id; // raw (decoded) AAS identifier - used to derive the S3 key / asset id

// Standard AAS v3 "Environment" shape (IDTA Part 2 JSON schema), so the file is a valid
// AASX-Package-Explorer-importable / AAS-tool-consumable document, not a custom envelope.
msg.payload = {
    assetAdministrationShells: [shell],
    submodels: submodels,
    conceptDescriptions: []
};
return msg;

(async function () {
    const { S3Client, PutObjectCommand } = awsS3Sdk;

    // Node-RED's function sandbox has no global fetch (regardless of Node.js version) - use the
    // built-in http/https modules (imported via Setup/libs below, since even core-module require()
    // is blocked inside the function body) instead of an extra npm dependency.
    function postJson(urlStr, headers, bodyObj) {
        return new Promise((resolve, reject) => {
            const u = new urlModule.URL(urlStr);
            const lib = u.protocol === 'http:' ? httpModule : httpsModule;
            const bodyStr = JSON.stringify(bodyObj);
            const req = lib.request(u, {
                method: 'POST',
                headers: Object.assign({ 'Content-Length': Buffer.byteLength(bodyStr) }, headers)
            }, (res) => {
                let data = '';
                res.on('data', (chunk) => { data += chunk; });
                res.on('end', () => {
                    resolve({ status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, body: data });
                });
            });
            req.on('error', reject);
            req.write(bodyStr);
            req.end();
        });
    }

    function getJson(urlStr, headers) {
        return new Promise((resolve, reject) => {
            const u = new urlModule.URL(urlStr);
            const lib = u.protocol === 'http:' ? httpModule : httpsModule;
            const req = lib.request(u, { method: 'GET', headers }, (res) => {
                let data = '';
                res.on('data', (chunk) => { data += chunk; });
                res.on('end', () => {
                    resolve({ status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, body: data });
                });
            });
            req.on('error', reject);
            req.end();
        });
    }

    const bucket = (env.get('S3_BUCKET') || env.get('SDI_S3_BUCKET'));
    const region = (env.get('S3_REGION') || env.get('SDI_S3_REGION')) || 'auto';
    const endpoint = (env.get('S3_ENDPOINT') || env.get('SDI_S3_ENDPOINT')); // e.g. https://<ACCOUNT_ID>.r2.cloudflarestorage.com - leave empty for real AWS S3
    const publicBaseUrl = (env.get('S3_PUBLIC_BASE_URL') || env.get('SDI_S3_PUBLIC_URL')); // e.g. https://pub-xxxxxxxx.r2.dev (R2 "Public Development URL")
    const edcManagementUrl = (env.get('EDC_MANAGEMENT_URL') || env.get('SDI_EDC_MANAGEMENT_URL')); // e.g. https://hni-01.c-27d7c36.kyma.ondemand.com/management
    const edcApiKey = (env.get('EDC_API_KEY') || env.get('SDI_EDC_API_KEY'));
    const accessPolicyId = (env.get('EDC_ACCESS_POLICY_ID') || env.get('SDI_EDC_ACCESS_POLICY_ID'));
    const contractPolicyId = (env.get('EDC_CONTRACT_POLICY_ID') || env.get('SDI_EDC_CONTRACT_POLICY_ID'));

    if (!bucket) {
        throw new Error('Missing S3_BUCKET');
    }

    // EDC registration is optional for now - if the connector details aren't known yet,
    // skip step 2/3 and only do the S3 upload, so the Basyx->S3 path can be tested in isolation.
    const edcConfigured = !!(edcManagementUrl && edcApiKey && publicBaseUrl && accessPolicyId && contractPolicyId);
    if (!edcConfigured) {
        node.warn('EDC Management API not configured (EDC_MANAGEMENT_URL/EDC_API_KEY/S3_PUBLIC_BASE_URL/EDC_ACCESS_POLICY_ID/EDC_CONTRACT_POLICY_ID) - uploading to S3 only, skipping offer registration');
    }

    const aasId = msg.aasId;
    // Human-readable shell name (last path segment of the AAS id, e.g. "Kugelschreiber_TracePEN"
    // from "localhost/demo/aas/Kugelschreiber_TracePEN") instead of an opaque base64 blob, so
    // consumers can tell what a file/asset is without decoding anything.
    // Note: not guaranteed globally unique - two shells from different namespaces could share
    // the same trailing segment and overwrite each other in the bucket.
    const shellName = String(aasId).split('/').filter(Boolean).pop().replace(/[^A-Za-z0-9._-]/g, '_');
    const objectKey = 'aas/' + shellName + '.json';
    const assetId = 'aas-shell-' + shellName;
    const contractDefId = 'aas-contractdef-' + shellName;

    // 1. Upload the combined shell+submodels document to S3 (R2 needs endpoint + forcePathStyle).
    // Credentials are passed explicitly because env.get() values (Node-RED tab env vars) never
    // reach the real process.env that the AWS SDK's default credential chain reads from.
    const accessKeyId = (env.get('AWS_ACCESS_KEY_ID') || env.get('SDI_S3_ACCESS_KEY_ID'));
    const secretAccessKey = (env.get('AWS_SECRET_ACCESS_KEY') || env.get('SDI_S3_SECRET_ACCESS_KEY'));
    if (!accessKeyId || !secretAccessKey) {
        throw new Error('Missing AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY');
    }
    const s3ClientConfig = { region, credentials: { accessKeyId, secretAccessKey } };
    if (endpoint) {
        s3ClientConfig.endpoint = endpoint;
        s3ClientConfig.forcePathStyle = true;
    }
    const s3 = new S3Client(s3ClientConfig);
    await s3.send(new PutObjectCommand({
        Bucket: bucket,
        Key: objectKey,
        Body: JSON.stringify(msg.payload),
        ContentType: 'application/json'
    }));

    if (!edcConfigured) {
        msg.statusCode = 200;
        msg.payload = { status: 'ok', assetId, objectKey, edcOfferRegistered: false };
        node.send(msg);
        node.done();
        return;
    }

    const edcHeaders = { 'Content-Type': 'application/json', 'X-Api-Key': edcApiKey };

    // 2. Create the Asset - same HttpData/baseUrl shape as the existing "Create Asset" dashboard,
    // pointing at the object's public R2 URL. Check-then-create instead of relying on a 409: this
    // connector returns a 500 (not a clean 409) when re-POSTing an @id that already exists and is
    // already referenced by a ContractDefinition, so we must avoid ever re-POSTing an existing one.
    const existingAsset = await getJson(edcManagementUrl + '/v3/assets/' + encodeURIComponent(assetId), edcHeaders);
    if (!existingAsset.ok) {
        const assetBody = {
            '@context': {},
            '@type': 'Asset',
            '@id': assetId,
            properties: {
                name: 'AAS Shell ' + aasId,
                description: 'AAS Shell ' + aasId
            },
            dataAddress: {
                '@type': 'DataAddress',
                type: 'HttpData',
                baseUrl: publicBaseUrl.replace(/\/$/, '') + '/' + objectKey
            }
        };
        const assetRes = await postJson(edcManagementUrl + '/v3/assets', edcHeaders, assetBody);
        if (!assetRes.ok && assetRes.status !== 409) {
            throw new Error('Asset creation failed: ' + assetRes.status + ' ' + assetRes.body);
        }
    }

    // 3. Create the Contract Definition (the actual "offer") referencing the pre-existing shared
    // policies - same check-then-create reasoning as the Asset above.
    const existingCd = await getJson(edcManagementUrl + '/v3/contractdefinitions/' + encodeURIComponent(contractDefId), edcHeaders);
    if (!existingCd.ok) {
        const contractDefBody = {
            '@context': {},
            '@type': 'ContractDefinition',
            '@id': contractDefId,
            accessPolicyId: accessPolicyId,
            contractPolicyId: contractPolicyId,
            assetsSelector: {
                '@type': 'CriterionDto',
                operandLeft: 'https://w3id.org/edc/v0.0.1/ns/id',
                operator: '=',
                operandRight: assetId
            }
        };
        const cdRes = await postJson(edcManagementUrl + '/v3/contractdefinitions', edcHeaders, contractDefBody);
        if (!cdRes.ok && cdRes.status !== 409) {
            throw new Error('ContractDefinition creation failed: ' + cdRes.status + ' ' + cdRes.body);
        }
    }

    msg.statusCode = 200;
    msg.payload = { status: 'ok', assetId, objectKey, contractDefinitionId: contractDefId, edcOfferRegistered: true };
    node.send(msg);
    node.done();
})().catch(err => {
    node.error(err, msg);
    msg.statusCode = 500;
    msg.payload = { error: err.message };
    node.send(msg);
    node.done();
});
return null;
